/* Focused F3-F5 finalization family scenarios. */
function t9f_make_fixture($db,$requestId,$tag){
    $requestId=(int)$requestId; $cmd=$requestId-1; $rd=$requestId+1; $perf=$requestId+2; $fac=$tag.'-'.$requestId;
    $db->query('INSERT INTO m_puskesmas (kode_pkm,nama_puskesmas,status) VALUES (?,?,?)',[$fac,$tag,'aktif']);
    foreach([[$cmd,'dokter'],[$rd,'dokter'],[$perf,'dokter']] as $u){$db->query('INSERT INTO users (userId,nama,email,username,password,role,status,must_change_password,remark) VALUES (?,?,?,?,?,?,?,?,?)',[$u[0],$tag.$u[0],$tag.$u[0].'@invalid',$tag.$u[0],'x',$u[1],'aktif',0,$fac]);}
    foreach([$rd,$perf] as $u){$db->query('INSERT INTO puskesmas_staff (staff_id,kode_pkm,user_id,nama,profesi,status) VALUES (?,?,?,?,?,?)',[$u,$fac,$u,$tag,'dokter','aktif']);$db->query('INSERT INTO nakes_facility_placements (staff_id,facility_code,effective_from,status,created_by_user_id) VALUES (?,?,?,?,?)',[$u,$fac,'2026-01-01','active',$u]);}
    $ci=doclinc_dokter_identity_context($cmd,true);$ri=doclinc_dokter_identity_context($rd,true);$pi=doclinc_dokter_identity_context($perf,true);
    vcw_assert_true($cmd<$rd&&$cmd<$perf&&!empty($ci['valid'])&&($ci['account_type']??null)==='command_center','canonical command-center fixture');
    vcw_assert_true(!empty($ri['valid'])&&($ri['account_type']??null)==='personal','canonical responsible-doctor fixture');
    vcw_assert_true(!empty($pi['valid'])&&($pi['account_type']??null)==='personal','canonical performer fixture');
    $db->query('INSERT INTO requests (request_id,user_id,location,request_status,assigned_puskesmas_code,assigned_puskesmas_name,visit_status,consultation_mode,responsible_doctor_user_id,visit_performer_user_id) VALUES (?,?,?,?,?,?,?,?,?,?)',[$requestId,$rd,'x','Accepted',$fac,$tag,'completed','visit',$rd,$perf]);
    $db->query('INSERT INTO request_responsible_doctor_assignments (request_id,staff_id,user_id,assigned_by_user_id,status,assigned_at) VALUES (?,?,?,?,?,NOW(6))',[$requestId,$rd,$rd,$rd,'aktif']);$ra=(int)$db->insert_id();
    $db->query('INSERT INTO visit_dispositions (request_id,version_no,decision,urgency,created_by_user_id,idempotency_key,created_at) VALUES (?,?,?,?,?,?,NOW(6))',[$requestId,1,'visit','routine',$rd,$tag.'-disp-'.$requestId]);
    $db->query('INSERT INTO request_visit_performer_assignments (request_id,staff_id,user_id,assigned_by_user_id,status,assigned_at,completed_at) VALUES (?,?,?,?,?,NOW(6),NOW(6))',[$requestId,$perf,$perf,$rd,'selesai']);$va=(int)$db->insert_id();
    $db->query('INSERT INTO visit_results (request_id,visit_assignment_id,version_no,performer_user_id,performer_staff_id,status,draft_revision,findings_json,actions_json,created_at,updated_at,submitted_at,submitted_by_user_id,submission_key) VALUES (?,?,?,?,?,"submitted",0,"[]","[]",NOW(6),NOW(6),NOW(6),?,?)',[$requestId,$va,1,$perf,$perf,$perf,$tag.'-result-'.$requestId]);$vr=(int)$db->insert_id();
    $db->query('INSERT INTO clinical_reviews (request_id,visit_result_id,reviewer_user_id,responsible_assignment_id,decision,reviewed_at,idempotency_key) VALUES (?,?,?,?,?,NOW(6),?)',[$requestId,$vr,$rd,$ra,'approved',$tag.'-review-'.$requestId]);
    $db->query('INSERT INTO medicalrecords (request_id,diagnosis,treatment,recommendations,anamnesis,responsible_doctor_user_id,recorded_by_user_id) VALUES (?,?,?,?,?,?,?)',[$requestId,'d','t','r','a',$rd,$perf]);$record=(int)$db->insert_id();
    return ['request_id'=>$requestId,'rd'=>$rd,'perf'=>$perf,'record_id'=>$record,'facility'=>$fac];
}
$t9f_spawn=function($tmp,$gate,&$procs,$requestId,$actorUserId,$key,$ann){
    $cmd=escapeshellarg(PHP_BINARY).' '.escapeshellarg(__DIR__.'/finalization_worker.php').' '.implode(' ',array_map('escapeshellarg',[(int)$requestId,(int)$actorUserId,(string)$key,(string)$ann,(string)$gate]));
    $pipes=[];$p=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($p))throw new RuntimeException('worker_start_failed');
    $procs[]=[$p,$pipes];$deadline=microtime(true)+10;while(!is_file($ann)&&microtime(true)<$deadline)usleep(20000);vcw_assert_true(is_file($ann),'worker announce received');return[$p,$pipes];
};
$t9f_run_pair=function($db,$fixture,$keyA,$userA,$keyB,$userB,$label)use($collect,$t9f_spawn){
    $tmp=sys_get_temp_dir().'/t9f-'.$label.'-'.getmypid().'-'.bin2hex(random_bytes(3));mkdir($tmp,0777,true);$gate=$tmp.'/start';$procs=[];$a=$tmp.'/a.json';$b=$tmp.'/b.json';
    try{$wa=$t9f_spawn($tmp,$gate,$procs,$fixture['request_id'],$userA,$keyA,$a);$wb=$t9f_spawn($tmp,$gate,$procs,$fixture['request_id'],$userB,$keyB,$b);file_put_contents($gate,'x');$ra=$collect($wa);$rb=$collect($wb);return[$ra,$rb];}
    finally{if(is_file($gate))@unlink($gate);foreach($procs as $z){[$p,$pipes]=$z;if(is_resource($p)&&proc_get_status($p)['running'])proc_terminate($p);foreach($pipes as $h){if(is_resource($h))fclose($h);}if(is_resource($p))proc_close($p);}foreach(glob($tmp.'/*')?:[] as $f){@unlink($f);}@rmdir($tmp);}
};
