$f4loser=($f4r1['ok']??false)?$f4r2:$f4r1;$f4conf=$f4loser['code']??($f4loser['result']['safe_error_code']??null);$f4events=(int)$db->where_in('request_id',[$f4a['request_id'],$f4b['request_id']])->where('event_type','clinical_record.finalized')->count_all_results('request_events');vcw_assert_same(1,$f4events,'F4 one owner event');vcw_assert_same('FINALIZATION_KEY_CONFLICT',$f4conf,'F4 key conflict');echo "TASK9_FINALIZATION_CROSS_REQUEST_KEY_RACE=PASS\n";
